import { Component, OnInit } from '@angular/core';
import { JobService } from '../../../core/services/job.service';
import { AuthService } from '../../../core/services/auth.service';
import { ToastService } from '../../../core/services/toast.service';
import { Job } from '../../../core/models/job.model';
import { User } from '../../../core/models/user.model';
import { ApplicationService } from '../../../core/services/application.service';
@Component({
  selector: 'app-admin-dashboard',
  templateUrl: './admin-dashboard.component.html',
  styleUrls: ['./admin-dashboard.component.css']
})
export class AdminDashboardComponent implements OnInit {
  jobs: Job[] = [];
  currentUser: User | null = null;
  isLoading = true;
  hasError = false;

  totalJobsCount = 0;
  totalApplicationsEstimate = 0;

  constructor(
    private jobService: JobService,
    private applicationService: ApplicationService,
    private authService: AuthService,
    private toast: ToastService
  ) {}

  ngOnInit(): void {
    this.currentUser = this.authService.currentUserValue;
    this.fetchDashboardData();
  }

  fetchDashboardData(): void {
    this.isLoading = true;
    this.hasError = false;

    this.jobService.getAllJobs({ limit: 50 }).subscribe({
      next: (res) => {
        this.jobs = res.data || [];
        this.totalJobsCount = res.results || this.jobs.length;
        this.isLoading = false;
      },
      error: () => {
        this.hasError = true;
        this.isLoading = false;
      }
    });
  }

  deleteJob(id?: string): void {
    if (!id) return;
    if (confirm('Are you sure you want to delete this job as an administrator?')) {
      this.jobService.deleteJob(id).subscribe({
        next: () => {
          this.toast.success('Job Removed', 'The job has been removed by administrator action.');
          this.jobs = this.jobs.filter(j => (j._id || j.id) !== id);
          this.totalJobsCount--;
        },
        error: (err) => {
          this.toast.error('Action Failed', err.error?.message || 'Could not delete job.');
        }
      });
    }
  }
}
<div class="admin-dashboard-page container section-padding">
  <div class="page-header d-flex justify-content-between align-items-center mb-4 flex-wrap gap-2">
    <div>
      <div class="d-flex align-items-center gap-2 mb-1">
        <h1 class="page-title">Administrator Console</h1>
        <span class="badge badge-warning">Admin Access</span>
      </div>
      <p class="page-subtitle">Platform overview, system metrics, and complete job management.</p>
    </div>
    <div class="d-flex gap-2">
      <a routerLink="/jobs/create" class="btn btn-primary">
        <i class="fa-solid fa-plus"></i> Post Platform Job
      </a>
      <a routerLink="/pricing" class="btn btn-secondary">
        <i class="fa-solid fa-credit-card"></i> Payment Gateway
      </a>
    </div>
  </div>

  <!-- Stat Cards Grid -->
  <div class="grid-4 stats-cards-grid mb-4">
    <div class="card stat-widget">
      <div class="stat-widget-icon bg-indigo">
        <i class="fa-solid fa-briefcase"></i>
      </div>
      <div class="stat-widget-content">
        <span class="stat-val">{{ totalJobsCount }}</span>
        <span class="stat-name">Active Job Listings</span>
      </div>
    </div>

    <div class="card stat-widget">
      <div class="stat-widget-icon bg-emerald">
        <i class="fa-solid fa-users"></i>
      </div>
      <div class="stat-widget-content">
        <span class="stat-val">{{ totalApplicationsEstimate }}</span>
        <span class="stat-name">Total Applications</span>
      </div>
    </div>

    <div class="card stat-widget">
      <div class="stat-widget-icon bg-sky">
        <i class="fa-solid fa-building-user"></i>
      </div>
      <div class="stat-widget-content">
        <span class="stat-val">120+</span>
        <span class="stat-name">Registered Employers</span>
      </div>
    </div>

    <div class="card stat-widget">
      <div class="stat-widget-icon bg-amber">
        <i class="fa-solid fa-shield-halved"></i>
      </div>
      <div class="stat-widget-content">
        <span class="stat-val">100%</span>
        <span class="stat-name">System Health</span>
      </div>
    </div>
  </div>

  <!-- Loading State -->
  <app-loading-spinner *ngIf="isLoading" message="Fetching administrative records..."></app-loading-spinner>

  <!-- Error state -->
  <div class="alert alert-danger" *ngIf="hasError && !isLoading">
    <i class="fa-solid fa-circle-exclamation"></i>
    <div>Failed to load administrative data. <button class="btn btn-sm btn-outline-danger" (click)="fetchDashboardData()">Retry</button></div>
  </div>

  <!-- Recent Postings Table -->
  <div class="card overflow-hidden mt-4" *ngIf="!isLoading && !hasError">
    <div class="card-header d-flex justify-content-between align-items-center">
      <h3 class="card-table-title">All System Job Openings</h3>
      <span class="text-muted text-sm">{{ jobs.length }} listings loaded</span>
    </div>

    <div class="table-responsive">
      <table class="data-table">
        <thead>
          <tr>
            <th>Job Title</th>
            <th>Company</th>
            <th>Type</th>
            <th>Location</th>
            <th>Salary</th>
            <th class="text-right">Admin Actions</th>
          </tr>
        </thead>
        <tbody>
          <tr *ngFor="let job of jobs">
            <td>
              <a [routerLink]="['/jobs', job._id || job.id]" class="font-bold text-slate-900">
                {{ job.title }}
              </a>
            </td>
            <td>{{ job.companyName }}</td>
            <td><span class="badge badge-primary">{{ job.type }}</span></td>
            <td>{{ job.location }}</td>
            <td>{{ job.salary ? ('$' + job.salary.toLocaleString()) : 'Negotiable' }}</td>
            <td>
              <div class="d-flex justify-content-end gap-2">
                <a [routerLink]="['/jobs', job._id || job.id, 'applications']" class="btn btn-sm btn-primary">
                  <i class="fa-solid fa-users"></i>
                </a>
                <a [routerLink]="['/jobs', job._id || job.id, 'edit']" class="btn btn-sm btn-secondary">
                  <i class="fa-regular fa-pen-to-square"></i>
                </a>
                <button
                  type="button"
                  class="btn btn-sm btn-outline-danger"
